INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (440009353102015, ARRAY['"A user enters example.com and receives the matching IP address before connecting to the site. Which service most directly performs this name resolution?"'::jsonb, '"A page loads HTML successfully, but a separately linked style file cannot be fetched. Which request/result is most relevant to investigate?"'::jsonb, '"A form submits login details over an unencrypted HTTP connection. What is the primary risk?"'::jsonb, '"A browser sends web requests, but the app needs reliable, ordered delivery for the data. Which transport is typically appropriate?"'::jsonb, '"A real-time service prefers low overhead and can tolerate some packet loss without waiting for retransmission. Which transport may fit?"'::jsonb, '"A user needs to transfer a file to a server using the protocol named in the syllabus. Which choice fits?"'::jsonb, '"A developer serves the same HTML document over HTTP and HTTPS. What does the HTTPS version add when configured correctly?"'::jsonb, '"A site owner changes a domain''s DNS record but some users still reach the old server temporarily. Which explanation is plausible?"'::jsonb, '"A site is accessible from a network but not by entering its domain, while a known IP address works. Which issue is worth checking first?"'::jsonb, '"A website uses a numeric IPv4 address and a newer 128-bit IPv6 address. Which statement is correct?"'::jsonb]::jsonb[], ARRAY['"CSS"'::jsonb, '"HTML"'::jsonb, '"DNS"'::jsonb, '"FTP"'::jsonb, '"The table''s colspan"'::jsonb, '"The user''s keyboard layout"'::jsonb, '"The image''s alt text alone"'::jsonb, '"The stylesheet URL and server response for the CSS resource"'::jsonb, '"Credentials may be exposed in transit"'::jsonb, '"HTML elements stop being parsed"'::jsonb, '"DNS converts the password into a domain"'::jsonb, '"The CSS box model stops working"'::jsonb, '"CSS"'::jsonb, '"TCP"'::jsonb, '"FTP only"'::jsonb, '"UDP"'::jsonb, '"HTTPS"'::jsonb, '"TCP"'::jsonb, '"HTML"'::jsonb, '"UDP"'::jsonb, '"HTTP heading"'::jsonb, '"FTP"'::jsonb, '"CSS selector"'::jsonb, '"JPEG"'::jsonb, '"Guaranteed correctness of every page statement"'::jsonb, '"A mandatory CSS grid layout"'::jsonb, '"TLS protection for data exchanged between client and server"'::jsonb, '"Automatic correction of invalid HTML"'::jsonb, '"Cached DNS data may persist until its TTL or cache expires"'::jsonb, '"HTTPS disables IP addressing"'::jsonb, '"CSS specificity always overrides DNS"'::jsonb, '"HTML lists are controlling routing"'::jsonb, '"Table row span"'::jsonb, '"DNS/name resolution"'::jsonb, '"Font weight"'::jsonb, '"Image width"'::jsonb, '"Both versions are HTML tags"'::jsonb, '"IPv6 is a CSS stylesheet type"'::jsonb, '"IPv4 uses 128 bits and IPv6 uses 32"'::jsonb, '"IPv4 uses 32-bit addresses; IPv6 uses 128-bit addresses"'::jsonb]::jsonb[], ARRAY['2'::jsonb, '3'::jsonb, '0'::jsonb, '1'::jsonb, '3'::jsonb, '1'::jsonb, '2'::jsonb, '0'::jsonb, '1'::jsonb, '3'::jsonb]::jsonb[]);

