""'::jsonb, '"alt=\"3\""'::jsonb, '"src=\"2\""'::jsonb, '"action=\"2\""'::jsonb, '"rowspan=\"2\""'::jsonb, '"colspan=\"2\""'::jsonb, '"The table header colour"'::jsonb, '"The CSS font-weight"'::jsonb, '"The form''s radio group"'::jsonb, '"The relative path from the current page"'::jsonb, '"style.css"'::jsonb, '"https://example.com/"'::jsonb, '"#heading"'::jsonb, '"submit"'::jsonb, '"hidden"'::jsonb, '"image only"'::jsonb, '"reset"'::jsonb, '"submit"'::jsonb, '"Its value is still submitted and must not be treated as secret merely because it is hidden"'::jsonb, '"It replaces HTTPS"'::jsonb, '"It automatically encrypts all form data"'::jsonb, '"It is invisible to the server"'::jsonb]::jsonb[], ARRAY['3'::jsonb, '0'::jsonb, '1'::jsonb, '2'::jsonb, '0'::jsonb, '2'::jsonb, '3'::jsonb, '1'::jsonb, '2'::jsonb, '0'::jsonb]::jsonb[]);

