INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (440919120103017, ARRAY['"Choose the sentence in which the modal expresses obligation rather than possibility."'::jsonb, '"Choose the correct verb form: “Neither the students nor the lab assistant ___ available.”"'::jsonb, '"Which revision corrects the passive voice error in “The instructions was printed yesterday”?"'::jsonb, '"Select the sentence with correct parallel structure."'::jsonb, '"A passage states that a new bus route cut a journey from 50 minutes to 35 minutes. What is the decrease in travel time?"'::jsonb, '"A passage says “Some students prefer printed notes, while others revise using digital files.” Which inference is strongest?"'::jsonb, '"An application needs a clear purpose and the dates requested. Which opening is best?"'::jsonb, '"Which revision improves clarity: “Due to the fact that the device overheated, therefore we stopped the test”?"'::jsonb, '"A speaker has only 90 seconds to explain a process with six steps. What should they do?"'::jsonb, '"Which statement is the strongest closing for a recommendation presentation?"'::jsonb]::jsonb[], ARRAY['"The upload could finish soon."'::jsonb, '"The file might be corrupted."'::jsonb, '"Users must log out before maintenance."'::jsonb, '"The server may restart tonight."'::jsonb, '"have"'::jsonb, '"are"'::jsonb, '"were"'::jsonb, '"is"'::jsonb, '"The instructions were printed yesterday."'::jsonb, '"The instructions was print yesterday."'::jsonb, '"The instructions are printed yesterday by them."'::jsonb, '"The instruction were printing yesterday."'::jsonb, '"The role requires to plan, testing and documentation."'::jsonb, '"The role requires planning, testing and documenting results."'::jsonb, '"The role requires planning, to test and documentation results."'::jsonb, '"The role requires planning, testing and to document results."'::jsonb, '"25 minutes"'::jsonb, '"10 minutes"'::jsonb, '"20 minutes"'::jsonb, '"15 minutes"'::jsonb, '"All students dislike digital files."'::jsonb, '"Students may use different revision preferences."'::jsonb, '"Digital files cannot contain notes."'::jsonb, '"Printed notes always produce better marks."'::jsonb, '"Hey, I won''t be there."'::jsonb, '"You know why I am writing."'::jsonb, '"I request leave from 14 to 16 December because of a scheduled medical appointment."'::jsonb, '"This is about something I need."'::jsonb, '"Because the device overheated, we stopped the test."'::jsonb, '"Because of the reason that the test stopped."'::jsonb, '"Due to the device overheating, therefore the test was stopped by us."'::jsonb, '"The device overheated, because therefore we stopped."'::jsonb, '"Read every detail at maximum speed"'::jsonb, '"Group related steps, highlight key actions, and leave time for a brief summary"'::jsonb, '"Skip the objective and repeat the title"'::jsonb, '"Show a dense slide and remain silent"'::jsonb, '"My slides are finished."'::jsonb, '"The topic is complicated, so no decision is possible."'::jsonb, '"That is all, and I do not know what to add."'::jsonb, '"To conclude, the trial met the stated criteria; I recommend a monitored rollout and review after one month."'::jsonb]::jsonb[], ARRAY['2'::jsonb, '3'::jsonb, '0'::jsonb, '1'::jsonb, '3'::jsonb, '1'::jsonb, '2'::jsonb, '0'::jsonb, '1'::jsonb, '3'::jsonb]::jsonb[]);

