VALUES (440009352101017, ARRAY['"A copied formula multiplies each row''s amount by the fixed tax rate in B1. Which reference keeps B1 fixed?"'::jsonb, '"Marks in B2:G2 are out of 100 each. Which formula calculates their percentage correctly?"'::jsonb, '"Column A lists departments and column B lists expenses. Sum expenses for IT only. Which formula fits?"'::jsonb, '"A row has six subject marks in B2:G2. Which formula calculates the total?"'::jsonb, '"H2 contains a percentage. Which formula returns Pass at 35% or above, otherwise Fail?"'::jsonb, '"A student''s percentage is 68%. Required bands are Distinction ≥70%, First Class ≥60%, Second Class ≥50%, Pass ≥35%, else Fail. Which result applies?"'::jsonb, '"A worksheet must keep columns A and B visible while scrolling horizontally. What should the user do?"'::jsonb, '"A staff list should display employees hired after 1 January 2025 without deleting other records. What should be used?"'::jsonb, '"A chart compares marks for six subjects in one class. Which is generally most direct?"'::jsonb, '"A cell must show the current date and time and update when recalculated. Which function is appropriate?"'::jsonb]::jsonb[], ARRAY['"$B$1"'::jsonb, '"$D$2"'::jsonb, '"B1"'::jsonb, '"B$2"'::jsonb, '"=AVERAGE(B2:G2)/100"'::jsonb, '"=SUM(B2:G2)/600*100"'::jsonb, '"=SUM(B2:G2)/6"'::jsonb, '"=COUNT(B2:G2)*100"'::jsonb, '"=NOW()"'::jsonb, '"=MAX(A:A)"'::jsonb, '"=SUMIF(A:A,\"IT\",B:B)"'::jsonb, '"=COUNT(A:A)"'::jsonb, '"=TODAY()"'::jsonb, '"=AVERAGE(B2:G2)"'::jsonb, '"=COUNTBLANK(B2:G2)"'::jsonb, '"=SUM(B2:G2)"'::jsonb, '"=IF(H2<35%,\"Pass\",\"Fail\")"'::jsonb, '"=IF(H2>=35%,\"Pass\",\"Fail\")"'::jsonb, '"=SUM(H2)"'::jsonb, '"=COUNT(H2)"'::jsonb, '"Second Class"'::jsonb, '"Pass"'::jsonb, '"Distinction"'::jsonb, '"First Class"'::jsonb, '"Freeze Panes from a selection immediately right of column B"'::jsonb, '"Merge columns A and B"'::jsonb, '"Freeze the bottom row"'::jsonb, '"Turn on Filter"'::jsonb, '"Sort only"'::jsonb, '"Delete older records"'::jsonb, '"Filter by the Hire Date condition"'::jsonb, '"Convert dates to plain text"'::jsonb, '"Unlabelled scatter chart"'::jsonb, '"Decorative image"'::jsonb, '"3-D pie chart with repeated slices"'::jsonb, '"Column chart with labelled subjects"'::jsonb, '"DATE()"'::jsonb, '"NOW()"'::jsonb, '"TODAY()"'::jsonb, '"DAY()"'::jsonb]::jsonb[], ARRAY['0'::jsonb, '1'::jsonb, '2'::jsonb, '3'::jsonb, '1'::jsonb, '3'::jsonb, '0'::jsonb, '2'::jsonb, '3'::jsonb, '1'::jsonb]::jsonb[]);

