jsonb, '"Shut down and disconnect power, use anti-static precautions, then check module compatibility and seating"'::jsonb, '"Pull the module out while running"'::jsonb]::jsonb[], ARRAY['1'::jsonb, '2'::jsonb, '3'::jsonb, '0'::jsonb, '2'::jsonb, '0'::jsonb, '1'::jsonb, '3'::jsonb, '0'::jsonb, '2'::jsonb]::jsonb[]);

