onb, '"Disconnect the old disk while the computer is running regardless of support"'::jsonb, '"Back up data, verify the new drive/interface, install with power disconnected, detect it, then partition/format only the new disk if required"'::jsonb, '"Copy files after erasing the only disk"'::jsonb, '"Replace the keyboard switches"'::jsonb, '"Use a dot-matrix driver"'::jsonb, '"Format the HDD"'::jsonb, '"Return to a supported resolution and verify input/cable compatibility"'::jsonb, '"Choose only by connector colour"'::jsonb, '"Match each peripheral''s interface with a supported computer port/adapter and driver"'::jsonb, '"Any connector can carry any data if forced"'::jsonb, '"Use the monitor port for serial data"'::jsonb, '"Whether the mouse is wireless"'::jsonb, '"Whether the printer uses impact dots"'::jsonb, '"How many partitions are on the hard disk"'::jsonb, '"Required graphics workload, compatibility, physical fit, power and cooling capacity"'::jsonb, '"HDD—magnetic; DVD—optical; USB flash drive—flash memory"'::jsonb, '"RAM—optical; HDD—CPU cache; DVD—magnetic card"'::jsonb, '"USB drive—CRT; DVD—RAM; HDD—keyboard"'::jsonb, '"HDD—optical; DVD—flash; USB drive—magnetic platter"'::jsonb, '"Keyboard switch force"'::jsonb, '"Pixel density"'::jsonb, '"Access time"'::jsonb, '"Speaker frequency"'::jsonb, '"Disk capacity"'::jsonb, '"Printer paper tray"'::jsonb, '"Optical disc colour"'::jsonb, '"PS/2 port/device support, port condition and firmware settings"'::jsonb, '"Run a long stress test while overheated"'::jsonb, '"Power down and reconnect/verify the fan, then test cooling and stability"'::jsonb, '"Format user files"'::jsonb, '"Leave it disconnected if the PC starts"'::jsonb]::jsonb[], ARRAY['0'::jsonb, '1'::jsonb, '2'::jsonb, '3'::jsonb, '1'::jsonb, '3'::jsonb, '0'::jsonb, '2'::jsonb, '3'::jsonb, '1'::jsonb]::jsonb[]);

