INSERT INTO public."TestsData" ("TestId", "Questions", "Options", "Answers")
VALUES (440091210101019, ARRAY['"A law restricts a citizen''s speech to address a public concern. The citizen argues Article 19 makes all restrictions invalid. Which reasoning is most defensible?"'::jsonb, '"An amendment changes an institution in a way alleged to eliminate judicial review and constitutional limits. Which framework most directly addresses whether a constitutional amendment can destroy foundational features?"'::jsonb, '"A government scheme promotes social welfare, but its implementation treats similarly situated citizens arbitrarily. Which constitutional analysis is strongest?"'::jsonb, '"A person challenges a deprivation of liberty and an arbitrary classification used to justify it. Which pair of Articles provides the most direct starting points?"'::jsonb, '"A student argues that the Preamble itself grants an unlimited legal power to an executive agency. What is the key flaw?"'::jsonb, '"A legislature enacts a law, and the executive implements it. A student claims the Election Commission is a third lawmaking House. Which correction is correct?"'::jsonb, '"A city municipal election and a Lok Sabha general election are both due. Which allocation matches the Constitution''s institutional design?"'::jsonb, '"The Council of Ministers remains in office despite losing Lok Sabha confidence, and the executive refuses to account to the House. Which principle is most directly implicated?"'::jsonb, '"An official says Article 14 guarantees identical treatment even where relevant circumstances differ. Which statement is more accurate?"'::jsonb, '"A Fundamental Right is asserted against a policy goal in Part IV. Which reading method best reflects the constitutional relationship?"'::jsonb]::jsonb[], ARRAY['"Identify the relevant Article 19 freedom and test whether the restriction is reasonable and falls within a constitutionally permitted ground"'::jsonb, '"Treat the restriction as a Fundamental Duty"'::jsonb, '"Decide solely by the location of the person''s district"'::jsonb, '"Declare every speech restriction invalid without examining the provision"'::jsonb, '"The ordinary rule for email notices"'::jsonb, '"The basic structure doctrine"'::jsonb, '"Article 51A only"'::jsonb, '"The municipal corporation framework"'::jsonb, '"Directive Principles automatically excuse unequal treatment"'::jsonb, '"Only Article 324 applies to all government actions"'::jsonb, '"Consider Part IV''s policy objective while separately testing implementation under Article 14 and relevant rights"'::jsonb, '"A welfare purpose removes the need for legal authority"'::jsonb, '"Articles 73 and 74"'::jsonb, '"Articles 243K and 243ZA"'::jsonb, '"Articles 51A and 324"'::jsonb, '"Articles 14 and 21"'::jsonb, '"The Preamble is the same as Article 51A"'::jsonb, '"The Preamble expresses constitutional values and aids interpretation; it does not independently grant unlimited executive authority"'::jsonb, '"The Preamble overrides all operative Articles"'::jsonb, '"Only the Preamble sets out local election procedures"'::jsonb, '"The ECI replaces Rajya Sabha in election years"'::jsonb, '"The ECI is the court of final appeal in every dispute"'::jsonb, '"The ECI is the Union Council of Ministers"'::jsonb, '"The ECI is a constitutional election authority, not a House of Parliament"'::jsonb, '"ECI handles Lok Sabha; State Election Commission handles the municipal poll"'::jsonb, '"Rajya Sabha runs municipal polls; ECI runs Lok Sabha poll"'::jsonb, '"Governor alone administers both"'::jsonb, '"Municipal Corporation runs both polls"'::jsonb, '"Municipal administration"'::jsonb, '"The Preamble''s wording about fraternity only"'::jsonb, '"Collective responsibility of the Union Council of Ministers to Lok Sabha"'::jsonb, '"Fundamental Duty to protect the environment"'::jsonb, '"Article 14 abolishes all classification"'::jsonb, '"Article 14 only concerns local elections"'::jsonb, '"Article 14 applies only to elected officials"'::jsonb, '"Equality requires equal protection and bars arbitrary discrimination, but reasonable classification may be constitutionally permitted"'::jsonb, '"Treat Directive Principles as criminal offences"'::jsonb, '"Read the provisions harmoniously, recognizing enforceable rights and the directive role of Part IV"'::jsonb, '"Assume both Parts have identical justiciability"'::jsonb, '"Always disregard Part IV"'::jsonb]::jsonb[], ARRAY['0'::jsonb, '1'::jsonb, '2'::jsonb, '3'::jsonb, '1'::jsonb, '3'::jsonb, '0'::jsonb, '2'::jsonb, '3'::jsonb, '1'::jsonb]::jsonb[]);

